sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !g_form.isNewRecord()) {
        return;
    }

	if (newValue === '') {
        return;
    }

    // Chama o Script Include para validar duplicidade de nome e cidade+estado
    var ga = new GlideAjax('ControlNameUtils');
    ga.addParam('sysparm_name', 'controlBase'); // Nome do método no Script Include
    ga.addParam('sysparm_base_name', g_form.getValue('name')); // Passa o nome da base


    // Envia a requisição ao Script Include
    ga.getXML(callBackFunction);

    function callBackFunction(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");

        if (answer === 'true') {
            // Exibe mensagem de erro se a base já existir com o mesmo nome ou cidade+estado
            g_form.addErrorMessage("There already exists a base with this name");
            g_form.clearValue('name');  // Limpa o valor do nome da base

        } else {
            // Se não houver duplicidade, limpa as mensagens de erro
            g_form.clearMessages();
        }
    }
}
